import sys

def solve():
    input_data = sys.stdin.read().split('\n')
    if not input_data:
        return

    first_line = input_data[0].strip()
    if not first_line:
        return

    H, W = map(int, first_line.split())

    grid = []
    for i in range(1, H + 1):
        grid.append(list(input_data[i]))

    def is_valid_char(c):
        if c == '+':
            return True
        if c.isspace():
            return True
        if c.isalnum():
            return True
        if c in '?', '!', ',', '.':
            return True
        return False

    def find_images(grid_h, grid_w, grid):
        images = []
        visited = [[False] * grid_w for _ in range(grid_h)]

        for r in range(grid_h):
            for c in range(grid_w):
                if grid[r][c] == '+' and not visited[r][c]:
                    # Check if this is a top-left corner of a valid image
                    # A top-left corner must have '+' to its right and '+' below it
                    if c + 1 < grid_w and r + 1 < grid_h:
                        if grid[r][c+1] == '+' and grid[r+1][c] == '+':
                            # BFS to find the bounding box of this connected '+' component
                            # But we know it's a rectangle. Let's just expand to find the full rectangle.
                            # Since borders don't touch, we can just expand right and down until we hit non-'+'
                            # However, the problem says "All '+' characters belong to the border of exactly 1 image".
                            # So a connected component of '+' is an image border.

                            # Let's do a BFS/DFS to collect all '+' connected to (r,c)
                            q = [(r, c)]
                            visited[r][c] = True
                            points = [(r, c)]

                            while q:
                                cr, cc = q.pop(0)
                                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                                    nr, nc = cr + dr, cc + dc
                                    if 0 <= nr < grid_h and 0 <= nc < grid_w:
                                        if not visited[nr][nc] and grid[nr][nc] == '+':
                                            visited[nr][nc] = True
                                            points.append((nr, nc))
                                            q.append((nr, nc))

                            # Now determine the bounding box of these points
                            min_r = min(p[0] for p in points)
                            max_r = max(p[0] for p in points)
                            min_c = min(p[1] for p in points)
                            max_c = max(p[1] for p in points)

                            # Verify it's a rectangle and at least 3x3
                            width = max_c - min_c + 1
                            height = max_r - min_r + 1

                            if width >= 3 and height >= 3:
                                # Check if all cells in the bounding box on the border are '+'
                                # And internal cells are not '+' (though internal could be other images, but their borders are separate)
                                # Actually, the rule "Borders of different images will not be adjacent" means we won't have two '+' from different images touching.
                                # So a connected component of '+' is definitely one image border.

                                # We need to verify that the bounding box is indeed filled with '+' on the perimeter.
                                valid_rect = True
                                for i in range(min_r, max_r + 1):
                                    for j in range(min_c, max_c + 1):
                                        # If it's on the border, it MUST be '+'
                                        if i == min_r or i == max_r or j == min_c or j == max_c:
                                            if grid[i][j] != '+':
                                                valid_rect = False
                                                break
                                    if not valid_rect:
                                        break

                                if valid_rect:
                                    images.append({'r': min_r, 'c': min_c, 'h': height, 'w': width})

        return images

    def get_banned_chars_inside_image(img, grid):
        r, c, h, w = img['r'], img['c'], img['h'], img['w']
        banned = []
        for i in range(r + 1, r + h - 1):
            for j in range(c + 1, c + w - 1):
                if not is_valid_char(grid[i][j]):
                    banned.append(grid[i][j])
        return banned

    def remove_image(img, grid):
        r, c, h, w = img['r'], img['c'], img['h'], img['w']
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = ' '

    # Step 1: Find all images
    images = find_images(H, W, grid)

    # Step 2: Identify banned characters inside each image
    # Map: banned_char -> list of images containing it
    banned_map = {}

    for img in images:
        chars = get_banned_chars_inside_image(img, grid)
        for ch in chars:
            if ch not in banned_map:
                banned_map[ch] = []
            banned_map[ch].append(img)

    # Step 3: For each banned char, find the smallest image containing it and flag for removal
    # "smallest image (in terms of pixel count)"
    images_to_remove = set()

    for ch, img_list in banned_map.items():
        # Sort by pixel count (h * w)
        sorted_imgs = sorted(img_list, key=lambda x: x['h'] * x['w'])
        # Remove the smallest one
        smallest = sorted_imgs[0]
        images_to_remove.add((smallest['r'], smallest['c']))

    # Step 4: Remove the flagged images
    for r, c in images_to_remove:
        # Find the image at (r, c)
        for img in images:
            if img['r'] == r and img['c'] == c:
                remove_image(img, grid)
                break

    # Step 5: Output the result
    output_lines = []
    for row in grid:
        output_lines.append("".join(row))
    print("\n".join(output_lines))

if __name__ == '__main__':
    solve()
